import{_ as e,o as a,c as o,a5 as r}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"HJ66 配置文件恢复","description":"中等 通过率：35.89% 时间限制：1秒 空间限制：32M 描述 有6条配置命令，它们执行的结果分别是： 命 令 执 行 reset reset what reset board board fault board add where to add board delete n。","frontmatter":{"title":"HJ66 配置文件恢复","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"中等 通过率：35.89% 时间限制：1秒 空间限制：32M 描述 有6条配置命令，它们执行的结果分别是： 命 令 执 行 reset reset what reset board board fault board add where to add board delete n。","sidebarWeight":102,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/多细节（简单）/HJ66 配置文件恢复.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/多细节（简单）/HJ66 配置文件恢复.md","filePath":"posts/前端面试与实战/03-算法训练/多细节（简单）/HJ66 配置文件恢复.md"}'),d={name:"posts/前端面试与实战/03-算法训练/多细节（简单）/HJ66 配置文件恢复.md"};function n(s,t,c,i,m,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<div><h1 id="hj66-配置文件恢复" tabindex="-1">HJ66 配置文件恢复 <a class="header-anchor" href="#hj66-配置文件恢复" aria-label="Permalink to &quot;HJ66 配置文件恢复&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ66 配置文件恢复”的核心思路，并能把它用于实际开发或面试表达。 中等 通过率：35.89% 时间限制：1秒 空间限制：32M <strong>描述</strong> 有6条配置命令，它们执行的结果分别是：</p></blockquote><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>命 令</td><td>执 行</td></tr><tr><td>reset</td><td>reset what</td></tr><tr><td>reset board</td><td>board fault</td></tr><tr><td>board add</td><td>where to add</td></tr><tr><td>board delete</td><td>no board at all</td></tr><tr><td>reboot backplane</td><td>impossible</td></tr><tr><td>backplane abort</td><td>install first</td></tr><tr><td><em>he he</em></td><td>unknown command</td></tr></tbody></table><p>注意：he he不是命令。</p><p>为了简化输入，方便用户，以“最短唯一匹配原则”匹配（注：需从首字母开始进行匹配）： 1、若只输入一字串，则只匹配一个关键字的命令行。例如输入：r，根据该规则，匹配命令reset，执行结果为：reset what；输入：res，根据该规则，匹配命令reset，执行结果为：reset what； 2、若只输入一字串，但匹配命令有两个关键字，则匹配失败。例如输入：reb，可以找到命令reboot backpalne，但是该命令有两个关键词，所有匹配失败，执行结果为：unknown command 3、若输入两字串，则先匹配第一关键字，如果有匹配，继续匹配第二关键字，如果仍不唯一，匹配失败。 例如输入：r b，找到匹配命令reset board 和 reboot backplane，执行结果为：unknown command。 例如输入：b a，无法确定是命令board add还是backplane abort，匹配失败。 4、若输入两字串，则先匹配第一关键字，如果有匹配，继续匹配第二关键字，如果唯一，匹配成功。例如输入：bo a，确定是命令board add，匹配成功。 5、若输入两字串，第一关键字匹配成功，则匹配第二关键字，若无匹配，失败。例如输入：b addr，无法匹配到相应的命令，所以执行结果为：unknow command。 6、若匹配失败，打印“unknown command”</p><p>注意：有多组输入。 数据范围：数据组数： 1≤<em>t</em>≤800 ，字符串长度 1≤<em>s</em>≤20 进阶：时间复杂度：<em>O</em>(<em>n</em>) ，空间复杂度： <em>O</em>(<em>n</em>) <strong>输入描述：</strong> 多行字符串，每行字符串一条命令 <strong>输出描述：</strong> 执行结果，每条命令输出一行 <strong>示例1</strong> 输入： resetreset boardboard addboard deletreboot backplanebackplane abort ==复制== 输出： reset whatboard faultwhere to addno board at allimpossibleinstall first</p><p>为了处理这个问题，我们可以首先将所有可能的命令及其对应的执行结果存储在一个字典中。然后，对于每一条输入命令，我们根据提供的规则来尝试匹配这些命令。以下是一个处理这个问题的Python代码示例：</p><h1 id="初始化命令和对应结果的字典" tabindex="-1">初始化命令和对应结果的字典 <a class="header-anchor" href="#初始化命令和对应结果的字典" aria-label="Permalink to &quot;初始化命令和对应结果的字典&quot;">​</a></h1><p>commands = { &quot;reset&quot;: &quot;reset what&quot;, &quot;reset board&quot;: &quot;board fault&quot;, &quot;board add&quot;: &quot;where to add&quot;, &quot;board delete&quot;: &quot;no board at all&quot;, &quot;reboot backplane&quot;: &quot;impossible&quot;, &quot;backplane abort&quot;: &quot;install first&quot; } def match_command(input_command): input_parts = input_command.split() # 将输入命令分割成单词 matches = [] for command in commands: command_parts = command.split() # 将每个可能的命令也分割成单词</p><h1 id="根据输入单词的数量和命令单词的数量进行匹配" tabindex="-1">根据输入单词的数量和命令单词的数量进行匹配 <a class="header-anchor" href="#根据输入单词的数量和命令单词的数量进行匹配" aria-label="Permalink to &quot;根据输入单词的数量和命令单词的数量进行匹配&quot;">​</a></h1><p>if len(input_parts) == len(command_parts) and all(cp.startswith(ip) for cp, ip in zip(command_parts, input_parts)): matches.append(command) # 添加匹配到的命令</p><h1 id="根据匹配到的命令数量决定输出" tabindex="-1">根据匹配到的命令数量决定输出 <a class="header-anchor" href="#根据匹配到的命令数量决定输出" aria-label="Permalink to &quot;根据匹配到的命令数量决定输出&quot;">​</a></h1><p>if len(matches) == 1: return commands[matches[0]] else: return &quot;unknown command&quot;</p><h1 id="循环读取并处理每一行输入直到eof" tabindex="-1">循环读取并处理每一行输入直到EOF <a class="header-anchor" href="#循环读取并处理每一行输入直到eof" aria-label="Permalink to &quot;循环读取并处理每一行输入直到EOF&quot;">​</a></h1><p>try: while True: input_command = input().strip() print(match_command(input_command)) except EOFError: pass</p><p>这段代码首先定义了一个字典 <code>commands</code>，包含所有可能的命令及其对应的执行结果。<code>match_command</code> 函数尝试根据输入匹配命令。它首先将输入命令分割成单词，然后遍历所有可能的命令，检查命令是否以输入的每个单词开始。如果找到唯一匹配的命令，它返回该命令的执行结果；如果没有找到匹配的命令或找到多个匹配的命令，它返回“unknown command”。</p><p>这种方法根据题目描述实现了“最短唯一匹配原则”，并且可以处理多组输入直到输入结束。对于给定的示例输入，这段代码能够正确输出各个命令的执行结果。</p><p>这行代码是Python中的一个非常强大的表达式，利用了列表推导（List Comprehension）和 <code>zip</code> 函数。我们来分步骤地解释它的作用：</p><h3 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>这行代码的目的是检查用户输入的命令（分割成多个部分，即<code>input_parts</code>）是否能够匹配到预定义命令列表中的某个命令（也分割成多个部分，即<code>command_parts</code>）。规则是，每个预定义命令的每一部分都必须以用户输入命令的对应部分开头。</p><h3 id="zip-函数" tabindex="-1"><code>zip</code> 函数 <a class="header-anchor" href="#zip-函数" aria-label="Permalink to &quot;`zip` 函数&quot;">​</a></h3><p><code>zip(command_parts, input_parts)</code> 将两个列表的相应元素配对，形成一个元组的序列。每个元组包含两个元素，第一个来自 <code>command_parts</code>（预定义命令的一部分），第二个来自 <code>input_parts</code>（用户输入命令的一部分）。</p><h3 id="循环" tabindex="-1">循环 <a class="header-anchor" href="#循环" aria-label="Permalink to &quot;循环&quot;">​</a></h3><p><code>for cp, ip in zip(command_parts, input_parts)</code> 遍历上述元组的序列，每次循环中，<code>cp</code> 是预定义命令的一部分，<code>ip</code> 是用户输入命令的一部分。</p><h3 id="条件表达式" tabindex="-1">条件表达式 <a class="header-anchor" href="#条件表达式" aria-label="Permalink to &quot;条件表达式&quot;">​</a></h3><p><code>cp.startswith(ip)</code> 检查预定义命令的这一部分（<code>cp</code>）是否以用户输入命令的相应部分（<code>ip</code>）开头。这个方法返回一个布尔值（<code>True</code> 或 <code>False</code>）。</p><h3 id="列表推导" tabindex="-1">列表推导 <a class="header-anchor" href="#列表推导" aria-label="Permalink to &quot;列表推导&quot;">​</a></h3><p><code>all(...)</code> 函数接收一个迭代器，并且当迭代器中所有元素都为 <code>True</code> 时，返回 <code>True</code>。在这个场景中，它检查是否所有配对的命令部分都满足 <code>startswith</code> 条件。</p><h3 id="综合解释" tabindex="-1">综合解释 <a class="header-anchor" href="#综合解释" aria-label="Permalink to &quot;综合解释&quot;">​</a></h3><p>所以，这整行代码 <code>all(cp.startswith(ip) for cp, ip in zip(command_parts, input_parts))</code> 检查用户输入的每个命令部分是否都是预定义命令相应部分的前缀。如果整个用户输入都符合这个规则，这表达式结果为 <code>True</code>，表示用户的输入与这个预定义命令匹配；否则，结果为 <code>False</code>。</p><p>这种方式非常有效地实现了对命令的“最短唯一匹配原则”的检查，同时保持了代码的简洁性。</p><p>import sys</p><p>def get_result(input_commands): inner_command_map = { &quot;reset&quot;: &quot;reset what&quot;, &quot;reset board&quot;: &quot;board fault&quot;, &quot;board add&quot;: &quot;where to add&quot;, &quot;board delete&quot;: &quot;no board at all&quot;, &quot;reboot backplane&quot;: &quot;impossible&quot;, &quot;backplane abort&quot;: &quot;install first&quot;, } inner_commands = inner_command_map.keys() def get_matches(user_command_str): user_command_parts = user_command_str.split() matches = [] for inner_command in inner_commands: result = [] inner_command_parts = inner_command.split() if len(inner_command_parts) == len(user_command_parts): for idx, ic in enumerate(inner_command_parts): if not ic.startswith(user_command_parts[idx]): break else: result.append(ic) else: continue if len(result) == len(inner_command_parts): matches.append(inner_command_map[inner_command]) if len(matches) == 1: return matches[0] else: return &#39;unknown command&#39; match_result = [get_matches(ic) for ic in input_commands] return match_result</p><p>input_commands = [line.strip() for line in sys.stdin] for i in get_result(input_commands): print(i)</p></div>',1)])])}const h=e(d,[["render",n]]);export{u as __pageData,h as default};
